CREATE OR REPLACE FUNCTION public.enforce_project_member_role_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_domain_type domain_type_enum;
BEGIN
  SELECT p.domain_type
  INTO v_domain_type
  FROM public.projects p
  WHERE p.id = NEW.project_id;

  IF v_domain_type IS NULL THEN
    RAISE EXCEPTION 'Invalid project_id % for project_members', NEW.project_id;
  END IF;

  IF NEW.abstract_role = 'regulatory_permit' AND v_domain_type <> 'mep' THEN
    RAISE EXCEPTION
      'Role regulatory_permit is only allowed for MEP projects (project_id=% domain_type=%)',
      NEW.project_id, v_domain_type;
  END IF;

  IF NEW.abstract_role = 'equipment_custodian' AND v_domain_type <> 'mfg' THEN
    RAISE EXCEPTION
      'Role equipment_custodian is only allowed for MFG projects (project_id=% domain_type=%)',
      NEW.project_id, v_domain_type;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
